import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import type {Page} from 'playwright';
import type {PrismaClient} from '@prisma/client';
import {waitForBrowserJson} from './browser-poll';
export async function verifyMissingCategoriesAndCac(page:Page,origin:string,workspaceId:string,db:PrismaClient,check:(page:Page,phase:string)=>Promise<void>){
 const root=origin+'/dashboard/app/workspaces/'+workspaceId,names=['Missing browser '+randomUUID(),'CAC browser '+randomUUID()];
 async function prepare(name:string,rows:unknown[],mappings:[string,string][],marketing:boolean){
  await page.goto(root+'/studio?create=1');await page.getByRole('region',{name:'Choose dashboard type',exact:true}).getByRole('button',{name:marketing?/^Marketing performance\b/:/^Sales performance\b/}).click();await page.getByLabel('Dataset name',{exact:true}).fill(name);await page.getByLabel('CSV, JSON or Excel file',{exact:true}).setInputFiles({name:'fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(rows))});await page.getByRole('button',{name:'Upload and profile dataset',exact:true}).click();
  await waitForBrowserJson<{datasets:{name:string;status:string}[]}>(page,'/dashboard/app/api/workspaces/'+workspaceId+'/datasets',body=>body.datasets.some(d=>d.name===name&&d.status==='READY'),'New metric fixture');await page.reload();await page.getByRole('region',{name:'Choose dashboard type',exact:true}).getByRole('button',{name:marketing?/^Marketing performance\b/:/^Sales performance\b/}).click();await page.getByLabel('Dataset for a new dashboard',{exact:true}).selectOption({label:name});
  await page.getByText('Review suggested field meanings (not yet confirmed)',{exact:true}).click();for(const [field,concept] of mappings)await page.getByLabel('Meaning of '+field,{exact:true}).selectOption(concept);await page.getByRole('button',{name:'Save confirmed field meanings',exact:true}).click();await page.getByText('Field choices saved.',{exact:false}).waitFor();
  await page.getByText('Confirm business calculation rules',{exact:true}).click();
  for(const [label,value] of [['What does one row represent?',marketing?'RECORD':'ORDER'],['Currency structure','SINGLE'],['Revenue basis',marketing?'UNKNOWN':'NET'],['Cost basis',marketing?'UNKNOWN':'COGS'],['Refunds already included in revenue?',marketing?'unknown':'true'],['Discounts already included in revenue?',marketing?'unknown':'true'],['Tax already included in revenue?',marketing?'unknown':'false'],['Shipping already included in revenue?',marketing?'unknown':'false'],['Cancelled orders','ALREADY_EXCLUDED'],['Returned units','ALREADY_NETTED'],['Marketing attribution (source-reported only)',marketing?'SOURCE_REPORTED':'UNCONFIRMED'],['Marketing spend occurs once per source row (no campaign spend repeated per conversion)',marketing?'true':'false'],['Acquisition counts are source-attributed unique NEW customers without overlap across rows',marketing?'true':'false']])await page.getByLabel(label,{exact:true}).selectOption(value);
  await page.getByLabel('Three-letter currency code',{exact:true}).fill('USD');await page.getByRole('button',{name:'Save business rules',exact:true}).click();await page.getByText('Business rules saved.',{exact:false}).waitFor();await page.getByRole('button',{name:'Calculate metrics',exact:true}).click();const button=page.getByRole('button',{name:marketing?'Create marketing performance':'Create sales performance',exact:true});await button.waitFor();await button.click();return page.getByRole('region',{name:'Dashboard results',exact:true});
 }
 async function add(canvas:ReturnType<Page['getByRole']>,metric:string,dimension:string){await canvas.getByText('Add a widget',{exact:true}).click();await canvas.getByLabel('Metric',{exact:true}).selectOption(metric);await canvas.getByLabel('Presentation',{exact:true}).selectOption('BAR');await canvas.getByLabel('Group by',{exact:true}).selectOption(dimension);await canvas.getByRole('button',{name:'Add widget',exact:true}).click();await page.getByRole('button',{name:'Save changes',exact:true}).click();}
 try{
  await page.setViewportSize({width:1280,height:900});let canvas=await prepare(names[0],[{id:'001',amount:100,channel:null},{id:'002',amount:200,channel:'(Missing)'},{id:'003',amount:300,channel:'Web'}],[['id','ORDER'],['amount','REVENUE'],['channel','CHANNEL']],false);await canvas.locator('article').first().getByText('$600.00',{exact:true}).waitFor();await canvas.getByRole('region',{name:'Dashboard source quality',exact:true}).getByText('Dashboard source quality: Warning',{exact:true}).waitFor();await canvas.getByRole('region',{name:'Dashboard source quality',exact:true}).getByText('channel: 1 missing cell',{exact:true}).waitFor();await add(canvas,'REVENUE','channel');await canvas.getByRole('button',{name:'Inspect Revenue: Missing value (empty source cell) in channel',exact:true}).click();await canvas.locator('article').first().getByText('$100.00',{exact:true}).waitFor();const records=canvas.getByRole('region',{name:'Matching source records',exact:true});await records.getByRole('cell',{name:'001',exact:true}).waitFor();assert.equal(await records.getByRole('row').count(),2);await check(page,'missing-category-drilldown');
  await canvas.getByRole('button',{name:'Clear filters',exact:true}).click();await canvas.locator('article').first().getByText('$600.00',{exact:true}).waitFor();await canvas.getByRole('button',{name:'Inspect Revenue: (Missing)',exact:true}).click();await canvas.locator('article').first().getByText('$200.00',{exact:true}).waitFor();await records.getByRole('cell',{name:'002',exact:true}).waitFor();assert.equal(await records.getByRole('row').count(),2);
  await canvas.getByRole('button',{name:'Clear filters',exact:true}).click();await canvas.getByLabel('Filter by',{exact:true}).selectOption('channel');await canvas.getByLabel('Missing values only',{exact:true}).check();await canvas.getByRole('button',{name:'Apply filter',exact:true}).click();await canvas.locator('article').first().getByText('$100.00',{exact:true}).waitFor();await page.setViewportSize({width:390,height:844});await check(page,'missing-category-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  await page.setViewportSize({width:1280,height:900});canvas=await prepare(names[1],[{campaign:'Search',spend:100,acquired:4,attributed:400},{campaign:'Social',spend:50,acquired:1,attributed:100}],[['campaign','CHANNEL'],['spend','MARKETING_SPEND'],['acquired','MARKETING_ACQUISITIONS'],['attributed','ATTRIBUTED_REVENUE']],true);await canvas.locator('article').first().getByText('$150.00',{exact:true}).waitFor();await add(canvas,'MARKETING_CAC','campaign');await canvas.getByRole('img',{name:'Marketing customer acquisition cost by campaign; exact values in table',exact:true}).waitFor();await canvas.getByText('$25.00',{exact:true}).waitFor();await canvas.getByText('$50.00',{exact:true}).waitFor();await check(page,'confirmed-marketing-cac');await page.setViewportSize({width:390,height:844});await check(page,'confirmed-marketing-cac-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  console.log('PASS: actual JSON upload, field/business confirmation, missing/literal category isolation, source rows, explicit CAC confirmation and grouped ratios, desktop/mobile accessibility.');
 }catch(error){console.error('Missing/CAC browser failure:',error);throw error;}finally{const sources=await db.dashboardDataSource.findMany({where:{workspaceId,name:{in:names}},select:{id:true}}),datasets=await db.dashboardDataset.findMany({where:{workspaceId,sourceId:{in:sources.map(s=>s.id)}},select:{id:true}});await db.dashboardView.deleteMany({where:{workspaceId,datasetId:{in:datasets.map(d=>d.id)}}});await db.dashboardDataSource.deleteMany({where:{workspaceId,id:{in:sources.map(s=>s.id)}}});await page.setViewportSize({width:1280,height:900});await page.goto(root+'/studio');}
}
